int process_diag_message(struct sk_buff *skb, struct nlmsghdr *nlh) {
    int ret = -EINVAL;
    struct sock_diag_handler *handler = NULL;

    if (!skb || !nlh) {
        return -EINVAL;
    }

    if (nlh->nlmsg_len < sizeof(*nlh)) {
        return -EINVAL;
    }

    handler = sock_diag_lock_handler(nlh->nlmsg_type);
    if (!handler) {
        return -ENOENT;
    }

    if (!try_module_get(handler->owner)) {
        sock_diag_unlock_handler(handler);
        return -EINVAL;
    }

    if (handler->dump) {
        ret = handler->dump(skb, nlh);
    } else {
        ret = -EINVAL;
    }

    module_put(handler->owner);
    sock_diag_unlock_handler(handler);

    return ret;
}
